files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  padding: 1rem;
}

.card {
  background: #16213e;
  border-radius: 16px;
  padding: 2rem;
  width: 100%;
  max-width: 800px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  color: #e0e0e0;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
  color: #ffffff;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b8;
  margin-bottom: 2rem;
}

.swatches {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 0.75rem;
  margin-bottom: 2rem;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
}

.color-box {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  transition: border-color 0.2s;
}

.hex-label {
  font-size: 0.875rem;
  font-family: 'Courier New', monospace;
  font-weight: 600;
  color: #c0c0d0;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.lock-btn {
  background: rgba(255, 255, 255, 0.08);
  border: 2px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  padding: 0.4rem 0.6rem;
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
  color: #e0e0e0;
  min-width: 44px;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
}

.lock-btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.95);
}

.lock-btn[aria-pressed="true"] {
  background: #e94560;
  border-color: #e94560;
  color: #ffffff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: #d63850;
  border-color: #d63850;
}

.generate-btn {
  display: block;
  width: 100%;
  padding: 1rem 2rem;
  font-size: 1.125rem;
  font-weight: 600;
  font-family: inherit;
  background: #e94560;
  color: #ffffff;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
}

.generate-btn:hover {
  background: #d63850;
  box-shadow: 0 4px 16px rgba(233, 69, 96, 0.4);
}

.generate-btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 3px;
}

.generate-btn:active {
  transform: scale(0.98);
}

@media (max-width: 600px) {
  .card {
    padding: 1.5rem;
  }
  .swatches {
    grid-template-columns: repeat(5, 1fr);
    gap: 0.5rem;
  }
  .hex-label {
    font-size: 0.75rem;
  }
  .lock-btn {
    padding: 0.3rem;
    font-size: 0.875rem;
    min-width: 36px;
    min-height: 36px;
  }
}

@media (max-width: 400px) {
  .swatches {
    grid-template-columns: repeat(5, 1fr);
    gap: 0.35rem;
  }
  .hex-label {
    font-size: 0.65rem;
    letter-spacing: 0;
  }
  .lock-btn {
    min-width: 32px;
    min-height: 32px;
    font-size: 0.75rem;
  }
}

(function () {
  'use strict';

  var swatchesContainer = document.getElementById('swatches');
  var generateBtn = document.getElementById('generate');

  var swatches = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var a = s * Math.min(l, 1 - l);
    function f(n) {
      var k = (n + h / 30) % 12;
      var color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    }
    return '#' + f(0) + f(8) + f(4);
  }

  function generatePalette() {
    var baseHue = Math.random() * 360;
    var scheme = Math.random() < 0.5 ? 'analogous' : 'complementary';
    var hues = [];
    for (var i = 0; i < 5; i++) {
      if (scheme === 'analogous') {
        hues.push((baseHue + (i - 2) * 30 + 360) % 360);
      } else {
        hues.push((baseHue + i * 72) % 360);
      }
    }
    return hues.map(function (h) {
      var s = 60 + Math.random() * 20;
      var l = 45 + Math.random() * 20;
      return hslToHex(h, s, l);
    });
  }

  function renderSwatches() {
    swatchesContainer.innerHTML = '';
    swatches.forEach(function (swatch, index) {
      var swatchDiv = document.createElement('div');
      swatchDiv.className = 'swatch';

      var colorBox = document.createElement('div');
      colorBox.className = 'color-box';
      colorBox.style.backgroundColor = swatch.hex;

      var hexLabel = document.createElement('span');
      hexLabel.className = 'hex-label';
      hexLabel.textContent = swatch.hex;

      var lockBtn = document.createElement('button');
      lockBtn.className = 'lock-btn';
      lockBtn.type = 'button';
      lockBtn.setAttribute('aria-label', 'Lock color ' + swatch.hex);
      lockBtn.setAttribute('aria-pressed', swatch.locked ? 'true' : 'false');
      lockBtn.textContent = swatch.locked ? '\uD83D\uDD12' : '\uD83D\uDD13';
      lockBtn.addEventListener('click', function () {
        swatch.locked = !swatch.locked;
        renderSwatches();
      });

      swatchDiv.appendChild(colorBox);
      swatchDiv.appendChild(hexLabel);
      swatchDiv.appendChild(lockBtn);
      swatchesContainer.appendChild(swatchDiv);
    });
  }

  function regenerate() {
    var newPalette = generatePalette();
    swatches.forEach(function (swatch, index) {
      if (!swatch.locked) {
        swatch.hex = newPalette[index];
      }
    });
    renderSwatches();
  }

  function init() {
    var initialPalette = generatePalette();
    swatches = initialPalette.map(function (hex) {
      return { hex: hex, locked: false };
    });
    renderSwatches();
    generateBtn.addEventListener('click', regenerate);
  }

  init();
})();
